1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { createGate, QuotaExceededError } from '../src/index.js';
4	
5	const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
6	
7	test('stats exposes the documented keys in order', () => {
8	  const gate = createGate({ limit: 2, windowMs: 100 });
9	  assert.deepEqual(Object.keys(gate.stats()), [
10	    'limit',
11	    'windowMs',
12	    'inFlight',
13	    'waiting',
14	    'granted',
15	    'refused',
16	    'expired',
17	  ]);
18	  assert.deepEqual(gate.stats(), {
19	    limit: 2,
20	    windowMs: 100,
21	    inFlight: 0,
22	    waiting: 0,
23	    granted: 0,
24	    refused: 0,
25	    expired: 0,
26	  });
27	});
28	
29	test('grants up to the limit and refuses beyond it', async () => {
30	  const gate = createGate({ limit: 1, windowMs: 1000 });
31	  const handle = await gate.acquire();
32	  assert.equal(gate.stats().inFlight, 1);
33	  assert.equal(gate.stats().granted, 1);
34	  await assert.rejects(gate.acquire(), (err) => {
35	    assert.ok(err instanceof QuotaExceededError);
36	    assert.equal(err.name, 'QuotaExceededError');
37	    assert.equal(err.code, 'QUOTA_EXCEEDED');
38	    return true;
39	  });
40	  assert.equal(gate.stats().refused, 1);
41	  handle.release();
42	  assert.equal(gate.stats().inFlight, 0);
43	});
44	
45	test('validates constructor and acquire arguments', () => {
46	  assert.throws(() => createGate(), TypeError);
47	  assert.throws(() => createGate({ limit: 1.5, windowMs: 10 }), TypeError);
48	  assert.throws(() => createGate({ limit: '2', windowMs: 10 }), TypeError);
49	  assert.throws(() => createGate({ limit: 0, windowMs: 10 }), RangeError);
50	  assert.throws(() => createGate({ limit: 1, windowMs: 0 }), RangeError);
51	  assert.throws(() => createGate({ limit: 1, windowMs: 10, maxWaitMs: -1 }), RangeError);
52	  assert.throws(() => createGate({ limit: 1, windowMs: 10, maxWaitMs: 1.5 }), TypeError);
53	
54	  const gate = createGate({ limit: 3, windowMs: 1000 });
55	  for (const units of [0, 4]) {
56	    assert.throws(
57	      () => gate.acquire(units),
58	      (err) => {
59	        assert.ok(err instanceof RangeError);
60	        assert.match(err.message, /3/); // echoes the actual limit
61	        return true;
62	      },
63	    );
64	  }
65	  assert.throws(() => gate.acquire(1.5), TypeError);
66	  assert.throws(() => gate.acquire('1'), TypeError);
67	});
68	
69	test('release is idempotent and stale handles do not corrupt stats', async () => {
70	  const gate = createGate({ limit: 3, windowMs: 50 });
71	  const h1 = await gate.acquire(2);
72	  h1.release();
73	  h1.release(); // repeated release: no error, no stat change
74	  assert.equal(gate.stats().inFlight, 0);
75	
76	  const h2 = await gate.acquire(1);
77	  assert.equal(gate.stats().inFlight, 1);
78	  await sleep(90); // the window closes; occupations clear automatically
79	  assert.equal(gate.stats().inFlight, 0);
80	  h2.release(); // stale handle: no-op
81	  assert.equal(gate.stats().inFlight, 0);
82	});
83	
84	test('queued requests are granted in arrival order at the window flip', async () => {
85	  const gate = createGate({ limit: 2, windowMs: 60, maxWaitMs: 1000 });
86	  const h = await gate.acquire(2); // window full
87	  const order = [];
88	  const p1 = gate.acquire(1).then((handle) => {
89	    order.push(1);
90	    return handle;
91	  });
92	  const p2 = gate.acquire(1).then((handle) => {
93	    order.push(2);
94	    return handle;
95	  });
96	  assert.equal(gate.stats().waiting, 2);
97	  const [h1, h2] = await Promise.all([p1, p2]);
98	  assert.deepEqual(order, [1, 2]); // same-tick arrivals settle in arrival order
99	  assert.equal(gate.stats().waiting, 0);
100	  assert.equal(gate.stats().granted, 3);
101	  h.release();
102	  h1.release();
103	  h2.release();
104	});
105	
106	test('a queued request that does not fit blocks later ones (mixed sizes)', async () => {
107	  const gate = createGate({ limit: 3, windowMs: 60, maxWaitMs: 1000 });
108	  await gate.acquire(2);
109	  let bigResolved = false;
110	  let smallResolved = false;
111	  const pBig = gate.acquire(3).then((h) => {
112	    bigResolved = true;
113	    return h;
114	  });
115	  const pSmall = gate.acquire(1).then((h) => {
116	    smallResolved = true;
117	    return h;
118	  });
119	  await sleep(90); // first flip passed: the big head fits a fresh window
120	  assert.equal(bigResolved, true);
121	  assert.equal(smallResolved, false); // 3 of 3 used; small waits for the next flip
122	  await pSmall;
123	  assert.equal(smallResolved, true);
124	  await pBig;
125	});
126	
127	test('requests due at the flip moment expire instead of being granted', async () => {
128	  const gate = createGate({ limit: 1, windowMs: 60, maxWaitMs: 30 });
129	  await gate.acquire(1);
130	  await assert.rejects(gate.acquire(1), (err) => {
131	    assert.ok(err instanceof QuotaExceededError);
132	    assert.equal(err.code, 'WAIT_EXPIRED');
133	    return true;
134	  });
135	  assert.equal(gate.stats().expired, 1);
136	  assert.equal(gate.stats().granted, 1); // expiry won over allocation
137	});
138	
139	test('a patient queued request is granted at the window flip', async () => {
140	  const gate = createGate({ limit: 1, windowMs: 60, maxWaitMs: 1000 });
141	  await gate.acquire(1);
142	  const h = await gate.acquire(1); // granted at the first flip
143	  assert.equal(gate.stats().granted, 2);
144	  assert.equal(gate.stats().inFlight, 1);
145	  h.release();
146	});
147	
148	test('multiple waits expiring at the same tick all expire', async () => {
149	  const gate = createGate({ limit: 1, windowMs: 1000, maxWaitMs: 30 });
150	  await gate.acquire(1);
151	  const results = await Promise.allSettled([gate.acquire(1), gate.acquire(1)]);
152	  assert.equal(results[0].status, 'rejected');
153	  assert.equal(results[1].status, 'rejected');
