117	    targetRoot.poolUsed += units;
118	    target.poolDraw += units;
119	    if (target === targetRoot) {
120	      target.usedOwn += units;
121	      target.inFlight += units;
122	      return { ownPart: units, borrowPart: 0 };
123	    }
124	    const ownPart = Math.min(units, Math.max(0, target.limit - target.usedOwn));
125	    const borrowPart = units - ownPart;
126	    target.usedOwn += ownPart;
127	    target.inFlight += units;
128	    target.borrowedInFlight += borrowPart;
129	    return { ownPart, borrowPart };
130	  }
131	
132	  function makeHandle(target, ownPart, borrowPart, ownGen, poolRoot, poolGen) {
133	    const handle = {
134	      _active: true,
135	      _target: target,
136	      _ownPart: ownPart,
137	      _borrowPart: borrowPart,
138	      _ownGen: ownGen,
139	      _poolRoot: poolRoot,
140	      _poolGen: poolGen,
141	      release() {
142	        if (!this._active) return;
143	        this._active = false;
144	        this._target.openHandles.delete(this);
145	        if (this._ownGen !== this._target.ownGen) return; // window closed; cleared
146	        this._target.inFlight -= this._ownPart;
147	        if (this._borrowPart > 0 && this._poolGen === this._poolRoot.poolGen) {
148	          this._target.inFlight -= this._borrowPart;
149	          this._target.borrowedInFlight -= this._borrowPart;
150	        }
151	        // A stale poolGen means the root window already reclaimed the
152	        // borrowed part; the handle stays valid but must not subtract twice.
153	      },
154	    };
155	    handleSeq += 1; // keeps handles distinguishable without exposing internals
156	    target.openHandles.add(handle);
157	    return handle;
158	  }
159	
160	  function detachSignal(entry) {
161	    if (entry.signal !== null) {
162	      entry.signal.removeEventListener('abort', entry.onAbort);
163	      entry.signal = null;
164	    }
165	  }
166	
167	  // One queue entry leaves the queue exactly once, and exactly one of
168	  // granted / refused / expired / cancelled moves as a result.
169	  function settleEntry(entry, outcome) {
170	    if (entry.removed) return;
171	    const ownerRoot = entry.owner.root;
172	    entry.removed = true;
173	    ownerRoot.liveQueued -= 1;
174	    clearTimeout(entry.timer);
175	    detachSignal(entry);
176	    entry.owner.waiting -= entry.units;
177	    if (outcome === 'granted') {
178	      const { ownPart, borrowPart } = applyGrant(entry.owner, entry.units);
179	      entry.owner.granted += 1;
180	      entry.resolve(
181	        makeHandle(
182	          entry.owner,
183	          ownPart,
184	          borrowPart,
185	          entry.owner.ownGen,
186	          entry.owner.root,
187	          entry.owner.root.poolGen,
188	        ),
189	      );
190	      return;
191	    }
192	    if (outcome === 'refused') {
193	      entry.owner.refused += 1;
194	      entry.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
195	    } else if (outcome === 'cancelled') {
196	      entry.owner.cancelled += 1;
197	      entry.reject(
198	        new QuotaExceededError('CANCELLED', 'queued request was cancelled before quota was available'),
199	      );
200	    } else {
201	      entry.owner.expired += 1;
202	      entry.reject(
203	        new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
204	      );
205	    }
206	  }
207	
208	  function armEntry(entry, delay) {
209	    entry.timer = setTimeout(() => {
210	      if (entry.removed) return;
211	      const t = now();
212	      if (entry.deadline <= t) {
213	        settleEntry(entry, 'expired');
214	      } else {
215	        // A frozen or rolled-back mock clock is not a past deadline: wait the
216	        // remaining real delay instead of expiring early.
217	        armEntry(entry, Math.max(1, entry.deadline - t));
218	      }
219	    }, Math.max(1, delay));
220	    if (typeof entry.timer.unref === 'function') entry.timer.unref();
221	  }
222	
223	  // At the same moment expiry beats cancellation: an abort arriving once the
224	  // deadline has already passed settles as WAIT_EXPIRED.
225	  function onEntryAbort(entry) {
226	    if (entry.removed) return;
227	    if (entry.deadline <= now()) {
228	      settleEntry(entry, 'expired');
229	    } else {
230	      settleEntry(entry, 'cancelled');
231	    }
232	  }
233	
234	  function recomputeMinDeadline() {
235	    let min = Infinity;
236	    const q = root.queue;
237	    for (let i = root.head; i < q.length; i += 1) {
238	      const entry = q[i];
239	      if (!entry.removed && entry.deadline < min) min = entry.deadline;
240	    }
241	    root.minDeadline = min;
242	  }
243	
244	  // Expiry is judged before quota allocation: anything due at or before the
245	  // flip moment expires rather than being granted.
246	  function sweepExpired(t) {
247	    if (root.minDeadline > t) return;
248	    let min = Infinity;
249	    for (let i = root.head; i < root.queue.length; i += 1) {
250	      const entry = root.queue[i];
251	      if (entry.removed) continue;
252	      if (entry.deadline <= t) settleEntry(entry, 'expired');
253	      else if (entry.deadline < min) min = entry.deadline;
254	    }
255	    root.minDeadline = min;
256	  }
257	
258	  // Grant queued requests in arrival order, all-or-nothing; a request that
259	  // does not fit blocks every later one. New arrivals are queued behind
260	  // waiters instead of overtaking them, so the head is always served at the
261	  // next root window flip and nothing is postponed indefinitely.
262	  function allocate() {
263	    const q = root.queue;
264	    while (root.head < q.length) {
265	      const entry = q[root.head];
266	      if (entry.removed) {
267	        root.head += 1;
268	        continue;
269	      }
270	      if (!fits(entry.units)) break;
271	      root.head += 1;
272	      settleEntry(entry, 'granted');
273	    }
274	    if (root.head > 32 && root.head * 2 >= q.length) {
275	      root.queue = q.slice(root.head);
276	      root.head = 0;
277	    }
278	  }
279	
280	  function flipOwn(target) {
281	    now();
282	    target.ownGen += 1;
283	    target.usedOwn = 0;
284	    target.inFlight = 0; // occupations from the closed window clear automatically
285	    target.borrowedInFlight = 0;
286	  }
287	
288	  function flipRoot() {
289	    const t = now();
290	    sweepExpired(t);
291	    state.ownGen += 1;
292	    state.usedOwn = 0;
293	    state.inFlight = 0;
294	    state.borrowedInFlight = 0;
295	    // Reclaim borrowed quota from every family member. The reclaim does not
296	    // break admitted occupations: handles stay valid, only the borrowed
297	    // accounting settles, and the inFlight drop is visible in the same stats
298	    // snapshot as the pool window flip.
299	    state.poolGen += 1;
300	    state.poolUsed = 0;
301	    for (const member of state.members) {
302	      member.poolDraw = 0;
303	      if (member !== state) {
304	        member.inFlight -= member.borrowedInFlight;
305	        member.borrowedInFlight = 0;
306	      }
307	    }
308	    allocate();
309	  }
310	
311	  function onWindowFire() {
312	    if (state.isRoot) flipRoot();
313	    else flipOwn(state);
314	  }
315	
316	  state.timer = setInterval(onWindowFire, windowMs);
317	  if (typeof state.timer.unref === 'function') state.timer.unref();
318	
319	  // --- Runtime adjustments -------------------------------------------------
320	
321	  function validateHierarchyLimit(target, newLimit) {
322	    // "Must not pass over the direct parent" and "must not sit below a direct
323	    // child": only the direct neighbours constrain the value. Transitive
324	    // bounds already follow from theirs.
325	    if (target.parent !== null && newLimit > target.parent.limit) {
326	      throw new RangeError('limit must not exceed the direct parent limit');
327	    }
328	    for (const child of target.children) {
329	      if (child.limit > newLimit) {
330	        throw new RangeError('limit must not be below a direct child limit');
331	      }
332	    }
333	  }
334	
335	  // Shrink fallout: queued requests that can never fit are refused
336	  // immediately and leave the queue, so they never block later arrivals.
337	  // Occupations are never torn apart.
338	  function refuseUnfittable(ownerFilter, newLimit) {
339	    const q = root.queue;
340	    let touched = false;
341	    for (let i = root.head; i < q.length; i += 1) {
342	      const entry = q[i];
343	      if (!entry.removed && entry.units > newLimit && ownerFilter(entry.owner)) {
344	        settleEntry(entry, 'refused');
345	        touched = true;
346	      }
347	    }
348	    if (touched) recomputeMinDeadline();
349	  }
350	
351	  function updateLimit(newLimit) {
352	    assertInteger(newLimit, 'limit');
353	    if (newLimit <= 0) throw new RangeError('limit must be a positive integer');
354	    validateHierarchyLimit(state, newLimit);
355	    // Validation above throws before anything mutates, so an invalid call
356	    // produces no observable cut. The change and its shrink fallout are one
357	    // synchronous cut; waiters are never granted early.
358	    state.limit = newLimit;
359	    if (state.isRoot) {
360	      root.poolLimit = newLimit;
361	      refuseUnfittable(() => true, newLimit);
362	    } else {
363	      refuseUnfittable((owner) => owner === state, newLimit);
364	    }
365	  }
366	
367	  function updateWindowMs(newWindowMs) {
368	    assertInteger(newWindowMs, 'windowMs');
369	    if (newWindowMs <= 0) throw new RangeError('windowMs must be a positive integer');
370	    // The current window keeps running with a fresh, full length measured
371	    // from this adjustment. Used quota is not cleared, queued deadlines do
372	    // not move, and no request is granted early.
373	    state.windowMs = newWindowMs;
374	    clearInterval(state.timer);
375	    state.timer = setInterval(onWindowFire, newWindowMs);
376	    if (typeof state.timer.unref === 'function') state.timer.unref();
377	    now();
378	  }
379	
380	  function updateMaxWaitMs(newMaxWaitMs) {
381	    assertInteger(newMaxWaitMs, 'maxWaitMs');
382	    if (newMaxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');
383	    // Existing waiters keep their original enqueue time; only the cap moves.
384	    // Waiters already past the new deadline settle as expired on the spot;
385	    // nothing is granted early and no deadline moves backwards into life.
386	    state.maxWaitMs = newMaxWaitMs;
387	    const t = now();
388	    let changed = false;
389	    const q = root.queue;
390	    for (let i = root.head; i < q.length; i += 1) {
391	      const entry = q[i];
392	      if (entry.removed || entry.owner !== state) continue;
393	      const newDeadline = entry.enqueuedAt + newMaxWaitMs;
394	      if (newDeadline <= t) {
395	        settleEntry(entry, 'expired');
396	        changed = true;
397	        continue;
398	      }
399	      if (newDeadline !== entry.deadline) {
400	        entry.deadline = newDeadline;
401	        clearTimeout(entry.timer);
402	        armEntry(entry, newDeadline - t);
403	        changed = true;
404	      }
405	    }
406	    if (changed) recomputeMinDeadline();
407	  }
408	
409	  function collectSubtree(target) {
410	    const out = new Set();
411	    const stack = [target];
412	    while (stack.length > 0) {
413	      const node = stack.pop();
414	      out.add(node);
415	      for (const child of node.children) stack.push(child);
416	    }
417	    return out;
418	  }
419	
420	  function isDescendantOf(maybeDescendant, ancestor) {
421	    let node = maybeDescendant;
422	    while (node !== null) {
423	      if (node === ancestor) return true;
424	      node = node.parent;
425	    }
426	    return false;
427	  }
428	
429	  // Partition the old root queue at the moved subtree boundary, then merge
430	  // the moved entries into the new root queue preserving global arrival
431	  // order (entry.seq is assigned monotonically at enqueue time).
432	  function migrateQueue(oldRootState, newRootState, moved) {
433	    const staying = [];
434	    const movedEntries = [];
435	    let movedLive = 0;
436	    const oldQ = oldRootState.queue;
437	    for (let i = oldRootState.head; i < oldQ.length; i += 1) {
438	      const entry = oldQ[i];
439	      if (entry.removed) continue;
440	      if (moved.has(entry.owner)) {
441	        movedEntries.push(entry);
442	        movedLive += 1;
443	      } else {
444	        staying.push(entry);
445	      }
446	    }
447	    oldRootState.queue = staying;
448	    oldRootState.head = 0;
449	    oldRootState.liveQueued -= movedLive;
450	    oldRootState.minDeadline = Infinity;
451	    for (const entry of staying) {
452	      if (entry.deadline < oldRootState.minDeadline) oldRootState.minDeadline = entry.deadline;
453	    }
454	
455	    const existing = [];
456	    const newQ = newRootState.queue;
457	    for (let i = newRootState.head; i < newQ.length; i += 1) {
458	      const entry = newQ[i];
459	      if (!entry.removed) existing.push(entry);
460	    }
461	    const merged = [];
462	    let a = 0;
463	    let b = 0;
464	    while (a < existing.length || b < movedEntries.length) {
465	      if (b === movedEntries.length || (a < existing.length && existing[a].seq <= movedEntries[b].seq)) {
466	        merged.push(existing[a]);
467	        a += 1;
468	      } else {
469	        merged.push(movedEntries[b]);
470	        b += 1;
471	      }
472	    }
473	    newRootState.queue = merged;
474	    newRootState.head = 0;
475	    newRootState.liveQueued += movedLive;
476	    newRootState.minDeadline = Infinity;
477	    for (const entry of merged) {
478	      if (entry.deadline < newRootState.minDeadline) newRootState.minDeadline = entry.deadline;
479	    }
480	  }
481	
482	  function reparent(newParent) {
483	    if (
484	      newParent === null ||
485	      newParent === undefined ||
486	      typeof newParent !== 'object' ||
487	      gateState.get(newParent) === undefined
488	    ) {
489	      throw new TypeError('reparent target must be a gate created by createGate');
490	    }
491	    const newParentState = gateState.get(newParent);
492	    if (newParentState === state) {
493	      throw new RangeError('cannot reparent a gate under itself');
494	    }
495	    if (isDescendantOf(newParentState, state)) {
496	      throw new RangeError('cannot reparent a gate under one of its own descendants');
497	    }
498	    if (state.limit > newParentState.limit) {
499	      throw new RangeError('limit must not exceed the new parent limit');
500	    }
501	    // Every check above happens before any mutation: invalid reparents roll
502	    // back trivially and produce no cut.
503	
504	    const oldRootState = state.root;
505	    const newRootState = newParentState.root;
506	    const moved = collectSubtree(state);
507	    let subtreeDraw = 0;
508	    for (const node of moved) subtreeDraw += node.poolDraw;
509	
510	    if (oldRootState !== newRootState) {
511	      // Settle the borrow in the old family's window, then re-borrow from the
512	      // new family. Both sides of the trade are visible in the same
513	      // synchronous snapshot. If the new pool cannot cover the draw, the
514	      // whole reparent is rejected with nothing changed.
515	      if (newRootState.poolUsed + subtreeDraw > newRootState.poolLimit) {
516	        throw new QuotaExceededError(
517	          'QUOTA_EXCEEDED',
518	          'cannot reparent: the new family pool cannot cover the borrowed quota',
519	        );
520	      }
521	
522	      const oldDirectParent = state.parent;
523	      oldRootState.poolUsed -= subtreeDraw;
524	      newRootState.poolUsed += subtreeDraw;
525	      for (const node of moved) {
526	        oldRootState.members.delete(node);
527	        newRootState.members.add(node);
528	        node.root = newRootState;
529	        // Outstanding occupations keep their place in the new pool window:
530	        // their handles go stale exactly when the NEW pool flips.
531	        for (const handle of node.openHandles) {
532	          handle._poolRoot = newRootState;
533	          handle._poolGen = newRootState.poolGen;
534	        }
535	      }
536	      migrateQueue(oldRootState, newRootState, moved);
537	      if (oldDirectParent !== null) oldDirectParent.children.delete(state);
538	      newParentState.children.add(state);
539	      state.parent = newParentState;
540	      if (state === oldRootState) {
541	        // The old root gate becomes an ordinary child: its next window fire
542	        // is a plain own-window flip; the new root owns the shared pool.
543	        state.isRoot = false;
544	      }
545	    } else {
546	      // Same family: only the direct link moves; the shared pool is
547	      // untouched, so the old direct parent sees no cut at all.
548	      state.parent.children.delete(state);
549	      newParentState.children.add(state);
550	      state.parent = newParentState;
551	    }
552	  }
553	
554	  function acquire(units = 1, signal) {
555	    assertInteger(units, 'units');
556	    assertSignal(signal);
557	    if (units < 1 || units > state.limit) {
558	      throw new RangeError(`units must be between 1 and ${state.limit}`);
559	    }
560	    // A signal that fired before the call settles as CANCELLED without ever
561	    // entering the queue or touching quota.
562	    if (signal !== undefined && signal !== null && signal.aborted) {
563	      state.cancelled += 1;
564	      return Promise.reject(
565	        new QuotaExceededError('CANCELLED', 'acquire was cancelled before it could queue'),
566	      );
567	    }
568	    // A non-empty queue means earlier arrivals are still owed quota; new
569	    // requests must not overtake them even if they would fit.
570	    if (root.liveQueued === 0 && fits(units)) {
571	      const { ownPart, borrowPart } = applyGrant(state, units);
572	      state.granted += 1;
573	      return Promise.resolve(
574	        makeHandle(state, ownPart, borrowPart, state.ownGen, root, root.poolGen),
575	      );
576	    }
577	    if (maxWaitMs === 0) {
578	      state.refused += 1;
579	      return Promise.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
580	    }
581	    state.waiting += units;
582	    root.liveQueued += 1;
583	    return new Promise((resolve, reject) => {
584	      const t = now();
585	      const entry = {
586	        owner: state,
587	        units,
588	        resolve,
589	        reject,
590	        seq: (enqueueSeq += 1),
591	        enqueuedAt: t,
592	        deadline: t + state.maxWaitMs,
593	        timer: null,
594	        removed: false,
595	        signal: signal !== undefined && signal !== null ? signal : null,
596	        onAbort: null,
597	      };
598	      entry.onAbort = () => onEntryAbort(entry);
599	      if (entry.signal !== null) {
600	        entry.signal.addEventListener('abort', entry.onAbort, { once: true });
601	      }
602	      armEntry(entry, state.maxWaitMs);
603	      if (entry.deadline < root.minDeadline) root.minDeadline = entry.deadline;
604	      root.queue.push(entry);
605	    });
606	  }
607	
608	  function stats() {
609	    return {
610	      limit: state.limit,
611	      windowMs: state.windowMs,
612	      inFlight: state.inFlight,
613	      waiting: state.waiting,
614	      granted: state.granted,
615	      refused: state.refused,
616	      expired: state.expired,
617	      cancelled: state.cancelled,
618	    };
619	  }
620	
621	  const gate = { acquire, stats, updateLimit, updateWindowMs, updateMaxWaitMs, reparent };
622	  gateState.set(gate, state);
623	  return gate;
624	}
