function armEntry(entry, delay) {
  entry.timer = setTimeout(() => {
    if (entry.removed) return;
    const t = now();
    if (entry.deadline <= t) {
      settleEntry(entry, 'expired');
    } else {
      // A frozen or rolled-back mock clock is not a past deadline: wait the
      // remaining real delay instead of expiring early.
      armEntry(entry, Math.max(1, entry.deadline - t));
    }
  }, Math.max(1, delay));
  if (typeof entry.timer.unref === 'function') entry.timer.unref();
}

