168	    }
169	  }
170	
171	  // One queue entry leaves the queue exactly once, and exactly one of
172	  // granted / refused / expired / cancelled moves as a result.
173	  function settleEntry(entry, outcome) {
174	    if (entry.removed) return;
175	    const ownerRoot = entry.owner.root;
176	    entry.removed = true;
177	    ownerRoot.liveQueued -= 1;
178	    clearTimeout(entry.timer);
179	    detachSignal(entry);
180	    entry.owner.waiting -= entry.units;
181	    if (outcome === 'granted') {
182	      const { ownPart, borrowPart } = applyGrant(entry.owner, entry.units);
183	      entry.owner.granted += 1;
184	      entry.resolve(
185	        makeHandle(
186	          entry.owner,
187	          ownPart,
188	          borrowPart,
189	          entry.owner.ownGen,
190	          entry.owner.root,
191	          entry.owner.root.poolGen,
192	        ),
193	      );
194	      return;
195	    }
196	    if (outcome === 'refused') {
197	      entry.owner.refused += 1;
198	      entry.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
199	    } else if (outcome === 'cancelled') {
200	      entry.owner.cancelled += 1;
201	      entry.reject(
202	        new QuotaExceededError('CANCELLED', 'queued request was cancelled before quota was available'),
203	      );
204	    } else {
205	      entry.owner.expired += 1;
206	      entry.reject(
207	        new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
208	      );
209	    }
210	  }
211	
212	  // The wait timer measures real elapsed time, like the baseline. The
213	  // deadline field additionally gates window-flip sweeps when the monotonic
214	  // clock and the wall clock disagree (mocked/frozen clocks).
215	  function armEntry(entry, delay) {
216	    entry.timer = setTimeout(() => {
217	      if (entry.removed) return;
218	      settleEntry(entry, 'expired');
219	    }, Math.max(1, delay));
220	    if (typeof entry.timer.unref === 'function') entry.timer.unref();
221	  }
222	
223	  // At the same moment expiry beats cancellation: an abort arriving once the
224	  // deadline has already passed settles as WAIT_EXPIRED.
225	  function onEntryAbort(entry) {
226	    if (entry.removed) return;
227	    if (entry.deadline <= now()) {
228	      settleEntry(entry, 'expired');
229	    } else {
230	      settleEntry(entry, 'cancelled');
231	    }
232	  }
233	
234	  function recomputeMinDeadline() {
235	    const r = state.root;
236	    let min = Infinity;
237	    const q = r.queue;
238	    for (let i = r.head; i < q.length; i += 1) {
239	      const entry = q[i];
240	      if (!entry.removed && entry.deadline < min) min = entry.deadline;
241	    }
242	    r.minDeadline = min;
243	  }
244	
245	  // Expiry is judged before quota allocation: anything due at or before the
246	  // flip moment expires rather than being granted.
247	  function sweepExpired(t) {
248	    const r = state.root;
249	    if (r.minDeadline > t) return;
250	    let min = Infinity;
251	    for (let i = r.head; i < r.queue.length; i += 1) {
252	      const entry = r.queue[i];
253	      if (entry.removed) continue;
254	      if (entry.deadline <= t) settleEntry(entry, 'expired');
255	      else if (entry.deadline < min) min = entry.deadline;
256	    }
257	    r.minDeadline = min;
258	  }
259	
260	  // Grant queued requests in arrival order, all-or-nothing; a request that
261	  // does not fit blocks every later one. New arrivals are queued behind
262	  // waiters instead of overtaking them, so the head is always served at the
263	  // next root window flip and nothing is postponed indefinitely.
264	  function allocate() {
265	    const r = state.root;
266	    const q = r.queue;
267	    while (r.head < q.length) {
268	      const entry = q[r.head];
269	      if (entry.removed) {
270	        r.head += 1;
271	        continue;
272	      }
273	      if (!fits(entry.units)) break;
274	      r.head += 1;
275	      settleEntry(entry, 'granted');
276	    }
277	    if (r.head > 32 && r.head * 2 >= q.length) {
278	      r.queue = q.slice(r.head);
279	      r.head = 0;
280	    }
281	  }
282	
283	  function flipOwn(target) {
284	    now();
285	    target.ownGen += 1;
286	    target.usedOwn = 0;
287	    target.inFlight = 0; // occupations from the closed window clear automatically
288	    target.borrowedInFlight = 0;
289	    // Handles born in the closed window are inert now; drop them so handles
290	    // their holders never release cannot accumulate.
291	    for (const handle of target.openHandles) {
292	      if (handle._ownGen !== target.ownGen) target.openHandles.delete(handle);
293	    }
294	  }
295	
296	  function flipRoot() {
297	    const t = now();
298	    sweepExpired(t);
299	    state.ownGen += 1;
300	    state.usedOwn = 0;
301	    state.inFlight = 0;
302	    state.borrowedInFlight = 0;
303	    for (const handle of state.openHandles) {
304	      if (handle._ownGen !== state.ownGen) state.openHandles.delete(handle);
305	    }
306	    // Reclaim borrowed quota from every family member. The reclaim does not
307	    // break admitted occupations: handles stay valid, only the borrowed
308	    // accounting settles, and the inFlight drop is visible in the same stats
309	    // snapshot as the pool window flip.
310	    state.poolGen += 1;
311	    state.poolUsed = 0;
312	    for (const member of state.members) {
313	      member.poolDraw = 0;
314	      if (member !== state) {
315	        member.inFlight -= member.borrowedInFlight;
316	        member.borrowedInFlight = 0;
317	      }
318	    }
319	    allocate();
320	  }
321	
322	  function onWindowFire() {
323	    if (state.isRoot) flipRoot();
324	    else flipOwn(state);
325	  }
326	
327	  state.timer = setInterval(onWindowFire, windowMs);
328	  if (typeof state.timer.unref === 'function') state.timer.unref();
329	
330	  // --- Runtime adjustments -------------------------------------------------
331	
332	  function validateHierarchyLimit(target, newLimit) {
333	    // "Must not pass over the direct parent" and "must not sit below a direct
334	    // child": only the direct neighbours constrain the value. Transitive
335	    // bounds already follow from theirs.
336	    if (target.parent !== null && newLimit > target.parent.limit) {
337	      throw new RangeError('limit must not exceed the direct parent limit');
338	    }
339	    for (const child of target.children) {
340	      if (child.limit > newLimit) {
341	        throw new RangeError('limit must not be below a direct child limit');
342	      }
343	    }
344	  }
345	
346	  // Shrink fallout: queued requests that can never fit are refused
347	  // immediately and leave the queue, so they never block later arrivals.
348	  // Occupations are never torn apart.
349	  function refuseUnfittable(ownerFilter, newLimit) {
350	    const r = state.root;
351	    const q = r.queue;
352	    let touched = false;
353	    for (let i = r.head; i < q.length; i += 1) {
354	      const entry = q[i];
355	      if (!entry.removed && entry.units > newLimit && ownerFilter(entry.owner)) {
356	        settleEntry(entry, 'refused');
357	        touched = true;
358	      }
359	    }
360	    if (touched) recomputeMinDeadline();
361	  }
362	
363	  function updateLimit(newLimit) {
364	    assertInteger(newLimit, 'limit');
365	    if (newLimit <= 0) throw new RangeError('limit must be a positive integer');
366	    validateHierarchyLimit(state, newLimit);
367	    // Validation above throws before anything mutates, so an invalid call
368	    // produces no observable cut. The change and its shrink fallout are one
369	    // synchronous cut; waiters are never granted early.
370	    state.limit = newLimit;
371	    if (state.isRoot) {
372	      state.root.poolLimit = newLimit;
373	      refuseUnfittable(() => true, newLimit);
374	    } else {
375	      refuseUnfittable((owner) => owner === state, newLimit);
376	    }
377	  }
378	
379	  function updateWindowMs(newWindowMs) {
380	    assertInteger(newWindowMs, 'windowMs');
381	    if (newWindowMs <= 0) throw new RangeError('windowMs must be a positive integer');
382	    // The current window keeps running with a fresh, full length measured
383	    // from this adjustment. Used quota is not cleared, queued deadlines do
384	    // not move, and no request is granted early.
385	    state.windowMs = newWindowMs;
386	    clearInterval(state.timer);
387	    state.timer = setInterval(onWindowFire, newWindowMs);
388	    if (typeof state.timer.unref === 'function') state.timer.unref();
389	  }
390	
391	  function updateMaxWaitMs(newMaxWaitMs) {
392	    assertInteger(newMaxWaitMs, 'maxWaitMs');
393	    if (newMaxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');
394	    // Existing waiters keep their original enqueue time; only the cap moves.
395	    // Waiters already past the new deadline settle as expired on the spot;
396	    // nothing is granted early and no deadline moves backwards into life.
397	    state.maxWaitMs = newMaxWaitMs;
398	    const t = now();
399	    let changed = false;
400	    const r = state.root;
401	    const q = r.queue;
402	    for (let i = r.head; i < q.length; i += 1) {
403	      const entry = q[i];
404	      if (entry.removed || entry.owner !== state) continue;
405	      const newDeadline = entry.enqueuedAt + newMaxWaitMs;
406	      if (newDeadline <= t) {
407	        settleEntry(entry, 'expired');
408	        changed = true;
409	        continue;
410	      }
411	      if (newDeadline !== entry.deadline) {
412	        entry.deadline = newDeadline;
413	        clearTimeout(entry.timer);
414	        armEntry(entry, newDeadline - t);
415	        changed = true;
416	      }
417	    }
418	    if (changed) recomputeMinDeadline();
419	  }
420	
421	  function collectSubtree(target) {
422	    const out = new Set();
423	    const stack = [target];
424	    while (stack.length > 0) {
425	      const node = stack.pop();
426	      out.add(node);
427	      for (const child of node.children) stack.push(child);
428	    }
429	    return out;
430	  }
431	
432	  function isDescendantOf(maybeDescendant, ancestor) {
433	    let node = maybeDescendant;
434	    while (node !== null) {
435	      if (node === ancestor) return true;
436	      node = node.parent;
437	    }
438	    return false;
439	  }
440	
441	  // Partition the old root queue at the moved subtree boundary, then merge
442	  // the moved entries into the new root queue preserving global arrival
443	  // order (entry.seq is assigned monotonically at enqueue time).
444	  function migrateQueue(oldRootState, newRootState, moved) {
445	    const staying = [];
446	    const movedEntries = [];
447	    let movedLive = 0;
448	    const oldQ = oldRootState.queue;
449	    for (let i = oldRootState.head; i < oldQ.length; i += 1) {
450	      const entry = oldQ[i];
451	      if (entry.removed) continue;
452	      if (moved.has(entry.owner)) {
453	        movedEntries.push(entry);
454	        movedLive += 1;
455	      } else {
456	        staying.push(entry);
457	      }
458	    }
459	    oldRootState.queue = staying;
460	    oldRootState.head = 0;
461	    oldRootState.liveQueued -= movedLive;
462	    oldRootState.minDeadline = Infinity;
463	    for (const entry of staying) {
464	      if (entry.deadline < oldRootState.minDeadline) oldRootState.minDeadline = entry.deadline;
465	    }
466	
467	    const existing = [];
468	    const newQ = newRootState.queue;
469	    for (let i = newRootState.head; i < newQ.length; i += 1) {
470	      const entry = newQ[i];
471	      if (!entry.removed) existing.push(entry);
472	    }
473	    const merged = [];
474	    let a = 0;
475	    let b = 0;
476	    while (a < existing.length || b < movedEntries.length) {
477	      if (b === movedEntries.length || (a < existing.length && existing[a].seq <= movedEntries[b].seq)) {
478	        merged.push(existing[a]);
479	        a += 1;
480	      } else {
481	        merged.push(movedEntries[b]);
482	        b += 1;
483	      }
484	    }
485	    newRootState.queue = merged;
486	    newRootState.head = 0;
487	    newRootState.liveQueued += movedLive;
488	    newRootState.minDeadline = Infinity;
489	    for (const entry of merged) {
490	      if (entry.deadline < newRootState.minDeadline) newRootState.minDeadline = entry.deadline;
491	    }
492	  }
493	
494	  function reparent(newParent) {
495	    if (
496	      newParent === null ||
497	      newParent === undefined ||
498	      typeof newParent !== 'object' ||
499	      gateState.get(newParent) === undefined
500	    ) {
501	      throw new TypeError('reparent target must be a gate created by createGate');
502	    }
503	    const newParentState = gateState.get(newParent);
504	    if (newParentState === state) {
505	      throw new RangeError('cannot reparent a gate under itself');
506	    }
507	    if (isDescendantOf(newParentState, state)) {
508	      throw new RangeError('cannot reparent a gate under one of its own descendants');
509	    }
510	    if (state.limit > newParentState.limit) {
511	      throw new RangeError('limit must not exceed the new parent limit');
512	    }
513	    // Every check above happens before any mutation: invalid reparents roll
514	    // back trivially and produce no cut.
515	
516	    const oldRootState = state.root;
517	    const newRootState = newParentState.root;
518	    const moved = collectSubtree(state);
519	    let subtreeDraw = 0;
520	    for (const node of moved) subtreeDraw += node.poolDraw;
521	
522	    if (oldRootState !== newRootState) {
523	      // Settle the borrow in the old family's window, then re-borrow from the
524	      // new family. Both sides of the trade are visible in the same
525	      // synchronous snapshot. If the new pool cannot cover the draw, the
526	      // whole reparent is rejected with nothing changed.
527	      if (newRootState.poolUsed + subtreeDraw > newRootState.poolLimit) {
528	        throw new QuotaExceededError(
529	          'QUOTA_EXCEEDED',
530	          'cannot reparent: the new family pool cannot cover the borrowed quota',
531	        );
532	      }
533	
534	      const oldDirectParent = state.parent;
535	      oldRootState.poolUsed -= subtreeDraw;
536	      newRootState.poolUsed += subtreeDraw;
537	      for (const node of moved) {
538	        oldRootState.members.delete(node);
539	        newRootState.members.add(node);
540	        node.root = newRootState;
541	        // Outstanding occupations keep their place in the new pool window:
542	        // their handles go stale exactly when the NEW pool flips.
543	        for (const handle of node.openHandles) {
544	          handle._poolRoot = newRootState;
545	          handle._poolGen = newRootState.poolGen;
546	        }
547	      }
548	      migrateQueue(oldRootState, newRootState, moved);
549	      // The moved waiters carry deadlines stamped by the old family clock;
550	      // make the joined clock at least as large so the monotonic guarantee
551	      // survives the move and no deadline is judged already past by accident.
552	      if (oldRootState.lastNow > newRootState.lastNow) {
553	        newRootState.lastNow = oldRootState.lastNow;
554	      }
555	      if (oldDirectParent !== null) oldDirectParent.children.delete(state);
556	      newParentState.children.add(state);
557	      state.parent = newParentState;
558	      if (state === oldRootState) {
559	        // The old root gate becomes an ordinary child: its next window fire
560	        // is a plain own-window flip; the new root owns the shared pool.
561	        state.isRoot = false;
562	      }
563	    } else {
564	      // Same family: only the direct link moves; the shared pool is
565	      // untouched, so the old direct parent sees no cut at all.
566	      state.parent.children.delete(state);
567	      newParentState.children.add(state);
568	      state.parent = newParentState;
569	    }
570	  }
571	
572	  function acquire(units = 1, signal) {
573	    assertInteger(units, 'units');
574	    assertSignal(signal);
575	    if (units < 1 || units > state.limit) {
576	      throw new RangeError(`units must be between 1 and ${state.limit}`);
577	    }
578	    // A signal that fired before the call settles as CANCELLED without ever
579	    // entering the queue or touching quota.
580	    if (signal !== undefined && signal !== null && signal.aborted) {
581	      state.cancelled += 1;
582	      return Promise.reject(
583	        new QuotaExceededError('CANCELLED', 'acquire was cancelled before it could queue'),
584	      );
585	    }
586	    // A non-empty queue means earlier arrivals are still owed quota; new
587	    // requests must not overtake them even if they would fit.
588	    const r = state.root;
589	    if (r.liveQueued === 0 && fits(units)) {
590	      const { ownPart, borrowPart } = applyGrant(state, units);
591	      state.granted += 1;
592	      return Promise.resolve(
593	        makeHandle(state, ownPart, borrowPart, state.ownGen, r, r.poolGen),
594	      );
595	    }
596	    if (state.maxWaitMs === 0) {
597	      state.refused += 1;
598	      return Promise.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
599	    }
600	    state.waiting += units;
601	    r.liveQueued += 1;
602	    return new Promise((resolve, reject) => {
603	      const t = now();
604	      const entry = {
605	        owner: state,
606	        units,
607	        resolve,
608	        reject,
609	        seq: (enqueueSeq += 1),
610	        enqueuedAt: t,
611	        deadline: t + state.maxWaitMs,
612	        timer: null,
613	        removed: false,
614	        signal: signal !== undefined && signal !== null ? signal : null,
615	        onAbort: null,
616	      };
617	      entry.onAbort = () => onEntryAbort(entry);
618	      if (entry.signal !== null) {
619	        entry.signal.addEventListener('abort', entry.onAbort, { once: true });
620	      }
621	      armEntry(entry, state.maxWaitMs);
622	      if (entry.deadline < r.minDeadline) r.minDeadline = entry.deadline;
623	      r.queue.push(entry);
624	    });
625	  }
626	
627	  function stats() {
628	    return {
629	      limit: state.limit,
630	      windowMs: state.windowMs,
631	      inFlight: state.inFlight,
632	      waiting: state.waiting,
633	      granted: state.granted,
634	      refused: state.refused,
635	      expired: state.expired,
636	      cancelled: state.cancelled,
637	    };
638	  }
639	
640	  const gate = { acquire, stats, updateLimit, updateWindowMs, updateMaxWaitMs, reparent };
641	  gateState.set(gate, state);
642	  return gate;
643	}
